import { join } from "node:path";

const workspace = process.env.HARNESS_BENCH_WORKSPACE;
const proxy = process.env.HARNESS_BENCH_PROXY_URL;
const model = process.env.HARNESS_BENCH_MODEL;
const prompt = process.env.HARNESS_BENCH_PROMPT_FILE;
if (!workspace || !proxy || !model || !prompt) throw new Error("Missing benchmark adapter environment");
const gatewayUrl = process.env.EVAL_GATEWAY_URL ?? "http://127.0.0.1:4477";
const headers = { Authorization: "Bearer fixture-preview-token", "Content-Type": "application/json" };
async function api(path: string, body: unknown): Promise<Record<string, unknown>> {
  const response = await fetch(`${gatewayUrl}${path}`, { method: "POST", headers, body: JSON.stringify(body) });
  const result = await response.json() as Record<string, unknown>;
  if (!response.ok || result.error) throw new Error(`Fixture API ${path} failed: ${String(result.error ?? response.status)}`);
  return result;
}
const provider = await api("/api/providers", { provider: "llamacpp", name: "Fixture provider", base_url: proxy, api_key: "fixture-local-proxy" });
const agent = await api("/api/agents", { name: "Fixture benchmark", type: "coder", memory_enabled: false, model, provider_id: provider.id, config: { max_context_tokens: 1_000_000, tool_profile: "coding", tool_execution_mode: "fused", tool_policy: { allow: ["read","write","edit","exec","grep","file_search","execute_code"] }, tool_policies: { read: "allow", write: "allow", edit: "allow", exec: "allow", grep: "allow", file_search: "allow", execute_code: "allow" }, model_params: { reasoning_effort: "high" } } });
const sessionId = `harness-${process.env.HARNESS_BENCH_RUN_ID ?? crypto.randomUUID()}`;
try {
  const warmup = "Initialize this local work session: use your programmatic execution tool to read warmup.json, compute the sum of its values and verify it using a second independent calculation. Do not read other files or write anything. Reply SESSION READY sum=13 after the check. The next message is the real task.";
  const warmupStarted = new Date().toISOString(); const warmClock = performance.now();
  const warmed = await api("/api/chat", {agentId:agent.id,sessionId,message:warmup,workspaceDir:workspace,tools:true,stream:false,maxOutputTokens:8192,modelParamsOverride:{reasoning_effort:"high"}});
  const warmupEnded = new Date().toISOString(); const warmMs=performance.now()-warmClock;
  if(warmed.failure || !(warmed.message as {content?:string})?.content?.includes("sum=13"))throw new Error("Warmup verification failed");
  const taskStarted=new Date().toISOString(); const taskClock=performance.now();
  const result = await api("/api/chat", { agentId: agent.id, sessionId, message: await Bun.file(prompt).text(), workspaceDir: workspace, tools: true, stream: false, maxOutputTokens: 8192, modelParamsOverride: { reasoning_effort: "high" } });
  const taskEnded=new Date().toISOString(); const taskMs=performance.now()-taskClock;
  await Bun.write(join(workspace,".timing.json"),JSON.stringify({warmup_started_at:warmupStarted,warmup_ended_at:warmupEnded,warmup_ms:warmMs,task_started_at:taskStarted,task_ended_at:taskEnded,task_elapsed_ms:taskMs,same_agent:true,warmup_verified:true,failed:!!result.failure}));
  if (result.failure) throw new Error(`Agent run failed: ${JSON.stringify(result.failure)}`);
  await Bun.write(join(workspace, ".harness-response.json"), JSON.stringify({ contextUsage: result.contextUsage, tokenUsage: result.tokenUsage }));
  console.log(JSON.stringify({ success: true, sessionId }));
} finally {
  if (typeof agent.id === "string") await fetch(`${gatewayUrl}/api/agents/${agent.id}`, { method: "DELETE", headers });
  if (typeof provider.id === "string") await fetch(`${gatewayUrl}/api/providers/${provider.id}`, { method: "DELETE", headers });
}
